//! ⏸️ The real Actor loan checks out and receives in one owned asynchronous source context.
use semio_framework_actor::{ActorGuestPhase,OriginalActorInput,OriginalJobTurnLoan,RetainedTurnInput};
use semio_framework_job::{CancelToken,Generation,JobPayloadAuthority,OperationId,OriginalCallerSourceParent,RetainedCloneGrant,RetainedCloneProgress,StepBudget};
use std::{future::Future,pin::pin,task::{Context,Poll,RawWaker,RawWakerVTable,Waker}};

#[global_allocator]
static OWNED_TURN_HEAP:semio_framework_trace::HeapWitness=semio_framework_trace::HeapWitness;
fn clock()->Option<u64>{Some(1000)}
fn grant()->RetainedCloneGrant{RetainedCloneGrant{maximum_items:16,maximum_copy_bytes:4096,maximum_capacity_bytes:65536,maximum_release_bytes:65536,maximum_depth:64}}
fn source_parent()->OriginalCallerSourceParent{let grant=grant();let(cancel,_)=CancelToken::admit_root(grant).unwrap().unwrap();let(authority,_)=JobPayloadAuthority::admit(OperationId(17),Generation(9),grant).unwrap().unwrap();OriginalCallerSourceParent::admit(authority,cancel,grant).ok().unwrap().0}
fn clone_waker(_: *const())->RawWaker{RawWaker::new(std::ptr::null(),&WAKER)}
fn no_wake(_: *const()){}
static WAKER:RawWakerVTable=RawWakerVTable::new(clone_waker,no_wake,no_wake,no_wake);
fn require_owned_send<F:Future+Send>(future:F)->F{future}
fn finish<F:Future>(future:F)->F::Output{let waker=unsafe{Waker::from_raw(clone_waker(std::ptr::null()))};let mut cx=Context::from_waker(&waker);let mut future=pin!(future);for _ in 0..8{if let Poll::Ready(result)=future.as_mut().poll(&mut cx){return result}}panic!("original finite fixture future did not complete")}
struct SuspendOnce(bool);
impl Future for SuspendOnce{type Output=();fn poll(mut self:std::pin::Pin<&mut Self>,_:&mut Context<'_>)->Poll<()>{if self.0{Poll::Ready(())}else{self.0=true;Poll::Pending}}}
fn retire(mut parent:OriginalCallerSourceParent){for _ in 0..64{if parent.terminal_is_empty(){return}parent.close_step(grant()).unwrap();}panic!("actual original caller parent did not close")}

/// 🧾️ One wallet moves, then the unchanged borrowed issuing context receives the actual guest receipt after suspension.
#[test]
fn original_owned_async_actor_turn_keeps_exact_wallet_recipient_and_epoch(){
 let parent=source_parent();let mut sequence=73;let mut receipt=Default::default();let mut donor=parent.borrow_context(StepBudget::new(7,12345,grant()),clock,&mut sequence,&mut receipt).unwrap();donor.bind_original_source_epoch(19).unwrap();
 let original=RetainedTurnInput{operation:17,generation:9,epoch:19,grant:grant()};let mut actor=OriginalActorInput::new([81u8;7],original).ok().unwrap();let admission=actor.checkout_guest(grant()).unwrap().unwrap();
 let(parked,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||parent.park_owned_turn(&mut donor).unwrap().unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(donor.fuel_remaining(),0);assert_eq!(donor.retained_grant(),RetainedCloneGrant{maximum_items:0,maximum_copy_bytes:0,maximum_capacity_bytes:0,maximum_release_bytes:0,maximum_depth:0});assert_eq!(donor.retained_progress(),RetainedCloneProgress{copied_items:1,..Default::default()});actor.receive_guest_spent(admission,donor.retained_progress(),ActorGuestPhase::Ready).unwrap();let issued=actor.checkout_guest(parked.original_grant()).unwrap().unwrap();assert!(actor.checkout_guest(grant()).is_err());assert!(actor.return_actor_turn().is_err());drop(donor);
 let(mut returned,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||finish(require_owned_send(parked.execute(async|cx|{
  let recipient=cx.original_recipient_identity();let mut loan=OriginalJobTurnLoan::new();let budget=loan.checkout(issued,cx)?.unwrap();assert_eq!(budget.fuel,6);assert_eq!(budget.deadline_us,12345);assert_eq!(cx.original_source_epoch(),Some(19));assert_eq!(cx.latest_us(),Some(1000));assert_eq!(cx.next_preview_sequence().unwrap(),73);let mut target=[0;7];target.copy_from_slice(&[81;7]);SuspendOnce(false).await;assert_eq!(cx.original_recipient_identity(),recipient);assert_eq!(cx.fuel_remaining(),6);assert_eq!(cx.retained_grant(),budget.input.grant);loan.receive(budget.input,RetainedCloneProgress{copied_items:1,copied_bytes:7,..Default::default()},2,cx)?;assert!(loan.terminal_is_empty());Ok(target)
 }))));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(returned.work_units_spent(),2);assert_eq!(returned.fuel_remaining(),Some(4));assert_eq!(returned.original_epoch(),19);assert_eq!(returned.original_deadline_us(),12345);assert!(returned.receiving_refusal().is_none());assert_eq!(returned.original().unwrap().as_ref().unwrap(),&[81u8;7]);actor.receive_guest_spent(issued,returned.receipt(),ActorGuestPhase::Dispatched).unwrap();let final_receipt=actor.return_actor_turn().unwrap();assert_eq!(final_receipt.spent,RetainedCloneProgress{copied_items:2,copied_bytes:7,..Default::default()});assert_eq!(final_receipt.remaining.maximum_items,14);assert_eq!(actor.take_dispatched_input().unwrap(),Some([81;7]));
 let foreign=source_parent();let mut foreign_sequence=0;let mut foreign_receipt=Default::default();let mut foreign_cx=foreign.borrow_context(StepBudget::new(2,12345,grant()),clock,&mut foreign_sequence,&mut foreign_receipt).unwrap();assert!(returned.take_original_on_caller(&mut foreign_cx).is_err());assert_eq!(foreign_cx.retained_progress(),Default::default());assert_eq!(foreign_cx.fuel_remaining(),2);drop(foreign_cx);retire(foreign);let mut polling_receipt=Default::default();let mut poller=parent.borrow_context(StepBudget::new(2,12345,grant()),clock,&mut sequence,&mut polling_receipt).unwrap();poller.bind_original_source_epoch(20).unwrap();let(outcome,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||returned.take_original_on_caller(&mut poller).unwrap().unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(outcome.original.unwrap(),[81;7]);assert_eq!(poller.next_preview_sequence().unwrap(),74);assert!(outcome.receiving_refusal.is_none());let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||returned.close_source(&parent,&mut poller).unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(step.progress(),RetainedCloneProgress{copied_items:1,..Default::default()});assert_eq!(poller.retained_progress(),RetainedCloneProgress{copied_items:2,..Default::default()});assert_eq!(poller.retained_progress().copied_bytes,0);assert!(returned.terminal_is_empty());drop(poller);let(_,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||drop(returned));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));retire(parent);
}

/// 🚫️ A fresh polling slice cannot receive the loan; its original suspended context still can.
#[test]
fn original_owned_async_actor_turn_refuses_fresh_polling_wallet_without_losing_loan(){
 let parent=source_parent();let mut sequence=0;let mut receipt=Default::default();let mut donor=parent.borrow_context(StepBudget::new(7,12345,grant()),clock,&mut sequence,&mut receipt).unwrap();donor.bind_original_source_epoch(19).unwrap();let parked=parent.park_owned_turn(&mut donor).unwrap().unwrap();let input=RetainedTurnInput{operation:17,generation:9,epoch:19,grant:parked.original_grant()};drop(donor);let mut fresh_sequence=0;let mut fresh_receipt=Default::default();let mut fresh=parent.borrow_context(StepBudget::new(1,12346,grant()),clock,&mut fresh_sequence,&mut fresh_receipt).unwrap();fresh.bind_original_source_epoch(20).unwrap();
 let(mut returned,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||finish(parked.execute(async|cx|{let recipient=cx.original_recipient_identity();let mut loan=OriginalJobTurnLoan::new();let budget=loan.checkout(input,cx)?.unwrap();SuspendOnce(false).await;assert!(loan.receive(budget.input,Default::default(),2,&mut fresh).is_err());assert!(loan.pending().is_some());assert_eq!(fresh.retained_progress(),Default::default());assert_eq!(fresh.fuel_remaining(),1);assert_eq!(cx.original_recipient_identity(),recipient);loan.receive(budget.input,Default::default(),2,cx)?;Ok(7u64)})));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(returned.work_units_spent(),2);assert_eq!(returned.fuel_remaining(),Some(4));drop(fresh);let mut footer=Default::default();let mut cx=parent.borrow_context(StepBudget::new(2,12345,grant()),clock,&mut sequence,&mut footer).unwrap();let outcome=returned.take_original_on_caller(&mut cx).unwrap().unwrap();assert_eq!(outcome.original.unwrap(),7);returned.close_source(&parent,&mut cx).unwrap();assert!(returned.terminal_is_empty());drop(cx);drop(returned);retire(parent);
}

/// ⚠️ Overspent raw work survives saturated fuel; the complete original failure remains in its owned reply.
#[test]
fn original_owned_async_actor_turn_preserves_full_failure_and_raw_overspent_work(){
 let parent=source_parent();let mut sequence=0;let mut receipt=Default::default();let mut donor=parent.borrow_context(StepBudget::new(7,12345,grant()),clock,&mut sequence,&mut receipt).unwrap();donor.bind_original_source_epoch(19).unwrap();let parked=parent.park_owned_turn(&mut donor).unwrap().unwrap();drop(donor);let input=RetainedTurnInput{operation:17,generation:9,epoch:19,grant:parked.original_grant()};
 let(mut returned,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||finish(parked.execute(async|cx|->Result<(),semio_framework_job::OriginalTurnFailure>{let mut loan=OriginalJobTurnLoan::new();let budget=loan.checkout(input,cx)?.unwrap();SuspendOnce(false).await;loan.receive(budget.input,Default::default(),9,cx)?;Ok(())})));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(returned.work_units_spent(),9);assert_eq!(returned.fuel_remaining(),Some(0));assert!(returned.original().unwrap().is_err());let mut footer=Default::default();let mut cx=parent.borrow_context(StepBudget::new(2,12345,grant()),clock,&mut sequence,&mut footer).unwrap();let outcome=returned.take_original_on_caller(&mut cx).unwrap().unwrap();assert!(outcome.original.is_err());returned.close_source(&parent,&mut cx).unwrap();assert!(returned.terminal_is_empty());drop(cx);drop(returned);retire(parent);
}

/// 🏡️ The genuine Actor input moves with the future; its original receipt rejoins before another caller polls.
#[test]
fn original_owned_async_actor_issuer_moves_and_rejoins_before_polling(){
 let parent=source_parent();let mut sequence=73;let mut receipt=Default::default();let mut cx=parent.borrow_context(StepBudget::new(8,12345,grant()),clock,&mut sequence,&mut receipt).unwrap();cx.bind_original_source_epoch(19).unwrap();let original=RetainedTurnInput{operation:17,generation:9,epoch:19,grant:grant()};let mut actor=OriginalActorInput::new([81u8;7],original).ok().unwrap();let admission=actor.checkout_guest(grant()).unwrap().unwrap();cx.consume_retained(RetainedCloneProgress{copied_items:1,..Default::default()}).unwrap();cx.consume_fuel(1);actor.receive_guest_spent(admission,cx.retained_progress(),ActorGuestPhase::Ready).unwrap();
 let(parked,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||actor.park_owned_job_turn(&parent,&mut cx).ok().unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(cx.fuel_remaining(),0);assert_eq!(cx.retained_progress().copied_items,2);drop(cx);
 let(mut returned,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||finish(require_owned_send(parked.execute(ActorGuestPhase::Dispatched,async|input,cx|{let mut loan=OriginalJobTurnLoan::new();let budget=loan.checkout(input,cx)?.unwrap();assert_eq!(budget.fuel,6);let recipient=cx.original_recipient_identity();SuspendOnce(false).await;assert_eq!(cx.original_recipient_identity(),recipient);loan.receive(budget.input,RetainedCloneProgress{copied_items:1,copied_bytes:7,..Default::default()},2,cx)?;Ok([82u8;7])}))));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));let actor_receipt=returned.actor_receipt().unwrap();assert_eq!(actor_receipt.input,original);assert_eq!(actor_receipt.spent,RetainedCloneProgress{copied_items:3,copied_bytes:7,..Default::default()});assert_eq!(actor_receipt.remaining.maximum_items,13);assert!(returned.issuer_refusal().is_none());assert_eq!(returned.issuer().unwrap().original(),Some(&[81u8;7]));assert_eq!(returned.caller_return().fuel_remaining(),Some(4));assert_eq!(returned.caller_return().work_units_spent(),2);
 let mut footer=Default::default();let mut poll=parent.borrow_context(StepBudget::new(3,12345,grant()),clock,&mut sequence,&mut footer).unwrap();assert!(returned.take_original_issuer_on_caller(&mut poll).is_err());assert_eq!(poll.retained_progress(),Default::default());let(outcome,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||returned.take_original_on_caller(&mut poll).unwrap().unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(outcome.caller.original.unwrap(),[82u8;7]);assert!(outcome.issuer_refusal.is_none());let(mut issuer,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||returned.take_original_issuer_on_caller(&mut poll).unwrap().unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(issuer.take_dispatched_input().unwrap(),Some([81;7]));drop(issuer);returned.close_source(&parent,&mut poll).unwrap();assert_eq!(poll.retained_progress(),RetainedCloneProgress{copied_items:3,..Default::default()});assert!(returned.terminal_is_empty());drop(poll);drop(returned);retire(parent);
}

/// 🔗️ A genuine paid source loan lends only its existing cancellation node through a zero-allocation witness.
#[test]
fn original_source_loan_cancellation_witness_borrows_exact_parent_without_alias_birth(){
 let parent=source_parent();let mut sequence=0;let mut receipt=Default::default();let mut cx=parent.borrow_context(StepBudget::new(2,12345,grant()),clock,&mut sequence,&mut receipt).unwrap();let mut loan=parent.admit_loan(&mut cx).unwrap().unwrap();let(witness,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||loan.cancellation().unwrap());assert!(std::ptr::eq(witness,parent.cancellation().unwrap()));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(cx.retained_progress(),RetainedCloneProgress{copied_items:1,..Default::default()});loan.close_step(&parent,&mut cx).unwrap();assert!(loan.terminal_is_empty());let(error,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||loan.cancellation().is_err());assert!(error);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(cx.retained_progress(),RetainedCloneProgress{copied_items:2,..Default::default()});drop(loan);drop(cx);retire(parent);
}

/// 🛬️ A real bounded producer reserves, allocates, copies and releases through the same original supplier.
#[test]
fn original_native_decode_source_receives_actual_physical_producer_and_preserves_denial(){
 use semio_framework_job_native_decode::{OriginalNativeDecodeSource,OriginalNativeDecodePolicy,OriginalNativeDecodeIssued};
 let parent=source_parent();let mut sequence=0;let mut receipt=Default::default();let mut cx=parent.borrow_context(StepBudget::new(16,12345,grant()),clock,&mut sequence,&mut receipt).unwrap();
 let(mut source,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||OriginalNativeDecodeSource::empty(OriginalNativeDecodePolicy{maximum_owned_bytes:128}));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));
 for _ in 0..3{let(ready,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||source.admit_step(&mut cx).unwrap());assert!(!ready);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));}assert!(source.admit_step(&mut cx).unwrap());assert_eq!(source.owned_bytes(),Some(0));assert_eq!(cx.retained_progress().copied_items,3);drop(cx);
 let mut denied_receipt=Default::default();let mut denied=parent.borrow_context(StepBudget::new(8,12345,RetainedCloneGrant{maximum_capacity_bytes:0,..grant()}),clock,&mut sequence,&mut denied_receipt).unwrap();
 let(outcome,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||source.receive_step(&mut denied,|control,actual|{let value=control.allocate_vec::<u8>(64);OriginalNativeDecodeIssued{value,grant:actual,progress:Default::default(),work:0}}).unwrap().unwrap());assert!(outcome.value.is_err());assert!(outcome.receiving_refusal.is_none());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(denied.retained_progress(),Default::default());assert_eq!(source.owned_bytes(),Some(0));drop(denied);
 let mut actual_receipt=Default::default();let mut actual=parent.borrow_context(StepBudget::new(32,12345,grant()),clock,&mut sequence,&mut actual_receipt).unwrap();
 let(outcome,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||source.receive_step(&mut actual,|control,actual|{let value=control.allocate_vec::<u8>(64);let bytes=value.as_ref().map_or(0,Vec::capacity);OriginalNativeDecodeIssued{value,grant:actual,progress:RetainedCloneProgress{copied_items:1,retained_capacity_bytes:bytes,..Default::default()},work:1}}).unwrap().unwrap());assert!(outcome.receiving_refusal.is_none());let mut original=Some(outcome.value.unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(64,0));let pointer=original.as_ref().unwrap().as_ptr();assert_eq!(source.owned_bytes(),Some(64));
 let foreign=source_parent();let mut foreign_sequence=0;let mut foreign_receipt=Default::default();let mut foreign_cx=foreign.borrow_context(StepBudget::new(8,12345,grant()),clock,&mut foreign_sequence,&mut foreign_receipt).unwrap();let(refused,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||source.receive_step(&mut foreign_cx,|_,_|->OriginalNativeDecodeIssued<()>{panic!("foreign caller cannot reach the producer")}).is_err());assert!(refused);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(foreign_cx.retained_progress(),Default::default());assert_eq!(original.as_ref().unwrap().as_ptr(),pointer);drop(foreign_cx);retire(foreign);
 let(outcome,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||source.receive_step(&mut actual,|control,actual|{assert!(actual.maximum_copy_bytes>=3);let value=control.checkpoint().map(|_|{let target=original.as_mut().unwrap();assert!(target.capacity()-target.len()>=3);target.extend_from_slice(&[1,2,3]);});OriginalNativeDecodeIssued{value,grant:actual,progress:RetainedCloneProgress{copied_items:1,copied_bytes:3,..Default::default()},work:1}}).unwrap().unwrap());assert!(outcome.value.is_ok()&&outcome.receiving_refusal.is_none());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(original.as_ref().unwrap(),&[1,2,3]);
 let(outcome,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||source.receive_step(&mut actual,|_,actual|{assert!(actual.maximum_release_bytes>=64);drop(original.take());OriginalNativeDecodeIssued{value:Ok(()),grant:actual,progress:RetainedCloneProgress{copied_items:1,released_bytes:64,..Default::default()},work:1}}).unwrap().unwrap());assert!(outcome.receiving_refusal.is_none());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,64));assert_eq!(actual.retained_progress(),RetainedCloneProgress{copied_items:3,copied_bytes:3,retained_capacity_bytes:64,released_bytes:64});
 for _ in 0..8{if source.terminal_is_empty(){break}let(_,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||source.close_step(&mut actual).unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));}assert!(source.terminal_is_empty());drop(actual);drop(source);retire(parent);
}

/// 🧳️ An overspent raw producer reply retains its successful value beside the complete receiving refusal.
#[test]
fn original_native_decode_source_preserves_outcome_on_raw_work_receiving_refusal(){
 use semio_framework_job_native_decode::{OriginalNativeDecodeSource,OriginalNativeDecodePolicy,OriginalNativeDecodeIssued};
 let parent=source_parent();let mut sequence=0;let mut receipt=Default::default();let mut cx=parent.borrow_context(StepBudget::new(8,12345,grant()),clock,&mut sequence,&mut receipt).unwrap();let mut source=OriginalNativeDecodeSource::empty(OriginalNativeDecodePolicy{maximum_owned_bytes:128});for _ in 0..4{source.admit_step(&mut cx).unwrap();}drop(cx);
 let mut raw_receipt=Default::default();let mut raw=parent.borrow_context(StepBudget::new(1,12345,grant()),clock,&mut sequence,&mut raw_receipt).unwrap();let(outcome,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||source.receive_step(&mut raw,|_,grant|OriginalNativeDecodeIssued{value:Ok(81u8),grant,progress:Default::default(),work:9}).unwrap().unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(outcome.value.unwrap(),81);assert!(outcome.receiving_refusal.is_some());assert_eq!(outcome.work,9);assert_eq!(raw.original_work_units_spent(),9);assert_eq!(raw.fuel_remaining(),0);drop(raw);
 let mut close_receipt=Default::default();let mut close=parent.borrow_context(StepBudget::new(8,12345,grant()),clock,&mut sequence,&mut close_receipt).unwrap();for _ in 0..8{if source.terminal_is_empty(){break}source.close_step(&mut close).unwrap();}assert!(source.terminal_is_empty());drop(close);drop(source);retire(parent);
}
